<?php function pdvEsc($value) { return htmlspecialchars((string)($value ?? ''), ENT_QUOTES, 'UTF-8'); } $status = $_GET['status'] ?? ''; ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Caixa | Mercado+</title><link rel="stylesheet" href="style.css"></head><body><div class="shell"><aside class="sidebar"><div class="brand">mercado<span>+</span></div><div class="nav-label">Operação</div><nav class="nav"><a href="index.php">⌂ &nbsp; Visão geral</a><a href="index.php?controller=produto">▦ &nbsp; Produtos</a><a href="index.php?controller=estoque">↕ &nbsp; Estoque</a><a class="active" href="index.php?controller=pdv">▣ &nbsp; Caixa / PDV</a><a href="index.php?controller=vendas&action=listar">◷ &nbsp; Vendas</a></nav></aside><main class="main"><header class="topline"><div><p class="eyebrow">Terminal 01</p><h1>Caixa</h1><p class="muted">Selecione os produtos para montar a compra.</p></div><span class="badge">● Caixa aberto</span></header><div class="pdv-layout"><section class="panel"><div class="panel-head"><h2>Produtos disponíveis</h2></div><div class="product-search"><input id="busca" placeholder="Buscar por código ou descrição" oninput="filtrar()"></div><div class="product-list" id="produtos"><?php foreach ($produtos as $produto): if ($produto['ativo'] && $produto['estoque'] > 0): ?><button class="product-choice" data-search="<?= pdvEsc(strtolower($produto['codigo'] . ' ' . $produto['descricao'])) ?>" onclick="adicionar(<?= (int)$produto['id'] ?>)"><strong><?= pdvEsc($produto['descricao']) ?></strong><span><?= pdvEsc($produto['codigo']) ?> · R$ <?= number_format((float)$produto['preco_venda'], 2, ',', '.') ?></span></button><?php endif; endforeach; ?></div></section><section class="panel cart"><div class="panel-head"><h2>Compra atual</h2><button class="button light" type="button" onclick="limpar()">Limpar</button></div><div id="carrinho"><div class="empty">Nenhum produto adicionado.</div></div><div class="total"><span>Total</span><span id="total">R$ 0,00</span></div><form method="post" action="index.php?controller=pdv&action=finalizar" onsubmit="return finalizar()"><input type="hidden" name="itens" id="itens"><input type="hidden" name="total" id="totalInput"><div class="field"><label for="forma_pagamento">Forma de pagamento</label><select name="forma_pagamento" id="forma_pagamento" required><option value="DINHEIRO">Dinheiro</option><option value="CARTAO">Cartão</option><option value="PIX">Pix</option></select></div><div class="form-actions"><button class="button" type="submit">Finalizar venda</button></div></form></section></div></main></div><script>const produtos = <?= json_encode(array_map(function ($produto) { return ['id'=>(int)$produto['id'], 'descricao'=>$produto['descricao'], 'preco'=>(float)$produto['preco_venda'], 'estoque'=>(int)$produto['estoque']]; }, $produtos), JSON_UNESCAPED_UNICODE) ?>; let carrinho=[]; function moeda(v){return v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});} function adicionar(id){const p=produtos.find(item=>item.id===id);const item=carrinho.find(item=>item.produto_id===id);if(item){if(item.quantidade<p.estoque)item.quantidade++;}else carrinho.push({produto_id:p.id,descricao:p.descricao,quantidade:1,valor_unitario:p.preco,subtotal:p.preco});render();} function remover(id){carrinho=carrinho.filter(item=>item.produto_id!==id);render();} function render(){carrinho.forEach(item=>item.subtotal=item.quantidade*item.valor_unitario);const total=carrinho.reduce((s,item)=>s+item.subtotal,0);document.getElementById('total').textContent=moeda(total);document.getElementById('totalInput').value=total.toFixed(2);document.getElementById('carrinho').innerHTML=carrinho.length?carrinho.map(item=>`<div class="cart-row"><div><strong>${item.descricao}</strong><small>${item.quantidade} × ${moeda(item.valor_unitario)}</small></div><strong>${moeda(item.subtotal)}</strong><button class="remove" type="button" onclick="remover(${item.produto_id})">×</button></div>`).join(''):'<div class="empty">Nenhum produto adicionado.</div>';} function limpar(){carrinho=[];render();} function finalizar(){if(!carrinho.length){alert('Adicione pelo menos um produto.');return false;}document.getElementById('itens').value=JSON.stringify(carrinho.map(({produto_id,quantidade,valor_unitario,subtotal})=>({produto_id,quantidade,valor_unitario,subtotal})));return true;} function filtrar(){const termo=document.getElementById('busca').value.toLowerCase();document.querySelectorAll('.product-choice').forEach(item=>item.hidden=!item.dataset.search.includes(termo));}</script></body></html>
